  const result = extra.length ? blocked('ARGUMENTS', 'Unexpected arguments') :
    command === 'checkpoint' && first && second ? checkpoint(first, second) :
    command === 'publish' && first && !second ? publish(first) :
    blocked('ARGUMENTS', 'Use checkpoint <absolute-manifest> <absolute-event> or publish <absolute-checkpoint-receipt>')
